class Resource {
public:
    void method() {}
    int value = 0;
};

class SmartPtr {
    Resource* m_ptr;
public:
    SmartPtr(Resource* p) : m_ptr(p) {}
    ~SmartPtr() { delete m_ptr; }

    // Required for the pointer syntax (smart_ptr->member)
    // Must return a raw pointer or another object defining ->
    Resource* operator->() const {
        return m_ptr;
    }
};

